from typing import Any, Mapping

def count_key_value_pairs(mapping: Mapping[str, Any]) -> int:
    """
    Count the total number of key-value pairs, including those at any nested level, in the provided mapping.

    Args:
    mapping (Mapping[str, Any]): The input mapping.

    Returns:
    int: The total number of key-value pairs.
    """
    count = 0
    stack = [mapping]

    while stack:
        current_mapping = stack.pop()
        count += len(current_mapping)

        for value in current_mapping.values():
            if isinstance(value, Mapping):
                stack.append(value)

    return count

