            if key in r2:
                r2[key] = _upper_value(r2[key])
            new_rows.append(r2)
        return new_rows

    # list of lists/tuples
    if isinstance(table, list) and all(isinstance(r, (list, tuple)) for r in table):
        if not isinstance(column, int):
            raise TypeError("For list-of-lists input, column must be an int index.")
        idx = column
        new_rows: List[List[Any]] = []
        for row in table:
