    try:
        import polars as pl
    except Exception as e:
        raise ImportError(
            "This function requires polars. Install with: pip install \"polars>=0.20.0\"\n"
            f"Original error: {e}"
        )

    # normalize mapping to dict
    if isinstance(lst0, dict):
        mapping = dict(lst0)
    else:
        # expect an iterable of pairs
        try:
            mapping = {old: new for old, new in lst0}
        except Exception:
            raise TypeError(
                "lst0 must be a dict or an iterable of (old_name, new_name) pairs."
            )

    # record input type to return same type
