        except Exception as e:
            raise TypeError(f"Unable to convert input df0 to a polars DataFrame: {e}")

    # Only keep mapping keys that exist in the DataFrame columns
    existing_cols = set(pl_df.columns)
    mapping_existing = {old: new for old, new in mapping.items() if old in existing_cols}
    missing = [old for old in mapping.keys() if old not in existing_cols]
    if missing:
