      df = pd.DataFrame({'a':[1,2], 'b':[3,4]})
      convert_df_to_dict(df, 'records')
      -> [{'a':1,'b':3}, {'a':2,'b':4}]
    """
    # simple pandas version check (robust to additional suffixes like '2.2.0rc1')
    def _ver_tuple(v: str):
        m = re.match(r"(\d+)\.(\d+)\.(\d+)", v)
        if not m:
            return (0, 0, 0)
        return tuple(int(x) for x in m.groups())

    if _ver_tuple(pd.__version__) < (2, 2, 0):
        raise RuntimeError(f"This function requires pandas >= 2.2.0 (found {pd.__version__}).")

    # normalize orientation synonyms
    var = (var0 or "").strip().lower()
    synonyms = {'keys': 'columns', 'values': 'list'}
    if var in synonyms:
        var = synonyms[var]

    allowed_orients = {'columns', 'index', 'records', 'split', 'list', 'dict'}
    if var not in allowed_orients:
