from typing import Any, List, Tuple

def _make_hashable(obj: Any) -> Any:
    """
    Convert obj into a stable, hashable representation suitable for deduplication.
    Handles primitives, lists, tuples, sets, and dicts recursively. Falls back to repr
    for other unhashable/unknown types.
    """
    # Fast path for common hashable primitives
    if isinstance(obj, (str, bytes, int, float, bool, type(None))):
        return obj

    # Sequences (list, tuple)
    if isinstance(obj, (list, tuple)):
        return (type(obj).__name__, tuple(_make_hashable(e) for e in obj))

    # Sets and frozensets -> sort their hashable elements to get a deterministic representation
    if isinstance(obj, (set, frozenset)):
        return (type(obj).__name__, tuple(sorted(_make_hashable(e) for e in obj)))

    # Dictionaries -> sort items by key representation for determinism
    if isinstance(obj, dict):
        items = tuple(sorted((_make_hashable(k), _make_hashable(v)) for k, v in obj.items()))
        return ('dict', items)

    # Try using obj itself if it is hashable
    try:
        hash(obj)
        return obj
    except Exception:
        # Last resort: use repr (deterministic for most builtins/custom classes)
        return ('repr', repr(obj))

def unique_sorted(lst0: List[Any]) -> List[Any]:
    """
    Return a new list containing the unique items from lst0 in sorted order.
    Sorting uses Python's built-in comparison for the original items; all items
    must be mutually comparable (or a TypeError will be raised by sorted).
    """
    seen = set()
    unique_items: List[Any] = []

    for item in lst0:
        key = _make_hashable(item)
        if key not in seen:
            seen.add(key)
            unique_items.append(item)

    # Return sorted unique items. If items are not mutually comparable, sorted()
    # may raise TypeError; that's consistent with Python behavior.
    return sorted(unique_items)
